import json
from pathlib import Path

root = Path(__file__).parent / 'translations/ro/full/chunks'
translations = {
    't000047': 'Meths trăiesc într-o lume a unor privilegii de neimaginat, locuind în zgârie-nori care îi înalță la propriu deasupra mulțimilor. Au acces la cele mai bune corpuri create prin inginerie genetică, la tehnologie de vârf și la puterea de a modela societatea după bunul plac. Viața lor îndelungată le permite să joace jocuri politice și economice pe termen lung, manipulând evenimente vreme de decenii sau secole pentru a-și urmări interesele. În contrast puternic, majoritatea populației se luptă să trăiască într-o lume în care până și moartea a devenit o marfă. Pentru mulți, speranța unei vieți mai bune nu vine din urcarea obișnuită pe scara socială, ci din șansa de a fi așezați într-un corp mai bun. Săracii pot rămâne „în stivă” ani sau decenii, cu conștiința depozitată în așteptarea unei noi întrupări. Când revin în formă fizică, primesc adesea corpuri produse în masă, de calitate slabă, întruchipări la propriu ale statutului lor social. Această discrepanță creează o societate plină de tensiuni și conflicte.',
    't000048': 'Seria explorează cum această inegalitate extremă modelează fiecare latură a vieții, de la relațiile personale la aplicarea legii și politică. Poliția, de pildă, se află adesea între slujirea intereselor Meths și păstrarea ordinii printre clasele de jos, oglindind probleme reale de părtinire sistemică și corupție. Noțiunea de „moarte adevărată”, distrugerea unei stive corticale și sfârșitul definitiv al existenței unei persoane, capătă o însemnătate sporită în această lume. Devine crima supremă, singurul mod de a pune cu adevărat capăt vieții cuiva. Pentru bogați, aceasta creează o nouă vulnerabilitate, obligându-i să-și apere mereu stivele; pentru săraci, amenințarea morții definitive devine încă un instrument de opresiune. Altered Carbon explorează și felul în care inegalitatea produsă de tehnologie afectează mobilitatea socială. În teorie, oricine ar putea strânge avere de-a lungul mai multor vieți; în practică, sistemul îi favorizează pe cei deja puternici.',
    't000049': 'Meths își folosesc secolele de experiență și resursele uriașe ca să-și păstreze poziția, ridicând o barieră aproape de netrecut în fața celor care încearcă să urce pe scara socială. Seria nu ocolește felul în care inegalitatea se vede în mediul construit. Bay City, versiunea viitoare a orașului San Francisco, unde se petrece mare parte din acțiune, reprezintă viu această societate stratificată. La nivelul străzii este aglomerație, poluare și criminalitate; etajele de sus ale zgârie-norilor le oferă celor puțini privilegiați aer curat, spațiu și lux. O altă latură fascinantă este „inegalitatea învelișurilor”. Calitatea corpului în care locuiește cineva devine un semn vizibil al statutului social. Apar noi forme de discriminare și prejudecată, iar „rușinea învelișului” devine o problemă socială importantă. Oamenii sunt judecați nu doar după fapte sau capacități, ci și după calitatea corpului pe care îl poartă în acel moment. Seria arată și cum această inegalitate afectează diferitele colonii planetare.',
    't000050': 'Unele lumi sunt practic feude corporative, în care întreaga populație este prinsă în datorii față de familiile Meths conducătoare. Altele au încercat să construiască societăți mai egalitare, adesea prin controlul strict al tehnologiei stivelor. Diversitatea structurilor sociale de pe diferite planete adâncește explorarea inegalității și a organizării societății în această serie. Educația și accesul la informații devin și ele surse de inegalitate. Meths, cu secolele lor de cunoștințe și experiență acumulate, au un avantaj imens față de ceilalți. Controlează accesul la tehnologia avansată și la informații, întărindu-și astfel locul în vârful ierarhiei sociale. Lumea interlopă din Altered Carbon este o altă oglindă a acestei societăți inegale. Infracționalitatea devine una dintre puținele căi de ascensiune socială, unii oameni alegând activități ilegale în speranța că vor strânge destui bani pentru corpuri mai bune sau chiar pentru o șansă la nemurire virtuală. Seria atinge și felul în care viața extrem de lungă și inegalitatea schimbă relațiile de familie.',
    't000051': 'Familiile Meth pot dura secole întregi, cu puterea concentrată în mâinile unor patriarhi sau matriarhe aproape nemuritori. Apar structuri familiale complicate, adesea disfuncționale, foarte diferite de ideile tradiționale despre familie. Felul în care Altered Carbon înfățișează structura societății și inegalitatea este o critică puternică a tendințelor socioeconomice actuale. Ducând diferențele de avere și progresele tehnologice de astăzi la extremele lor logice, seria creează o viziune înfiorătoare asupra unui viitor în care distanța dintre bogați și săraci a devenit, la propriu, o chestiune de viață și de moarte.',
    't000052': 'Această latură a seriei îi îndeamnă pe spectatori să se gândească la urmările pe termen lung ale concentrării necontrolate a averii și la pericolele posibile atunci când tehnologii esențiale pentru prelungirea vieții sunt controlate de câțiva privilegiați. Ridică întrebări importante despre egalitate și dreptate într-o lume în care nici măcar moartea nu mai este o limită comună tuturor. Mai mult, seria ne provoacă să ne gândim la natura puterii și la felul în care aceasta ar putea evolua într-o societate de după moartea obișnuită. Când unii oameni pot acumula experiență și influență de-a lungul secolelor, cum se schimbă raporturile de putere socială și politică? Ce forme noi de rezistență și schimbare socială ar putea apărea împotriva unei inegalități atât de înrădăcinate? Explorând aceste teme, Altered Carbon trece dincolo de simplul divertisment și oferă o examinare provocatoare a inegalității sociale și a formelor pe care le-ar putea lua în viitor. Este o poveste de avertizare despre pericolul ca progresul tehnologic să amplifice, nu să micșoreze, diferențele sociale, îndemnându-i pe spectatori să se gândească la felul în care ne-am putea modela viitorul tehnologic mai echitabil.',
    't000053': 'Capitolul al șaptelea — Etică și moralitate într-o lume de după moarte',
    't000054': 'Universul Altered Carbon este plin de dileme etice complicate, multe izvorâte din schimbarea fundamentală a condiției umane prin învingerea morții. Această nouă realitate pune la încercare cadrele morale tradiționale și le cere atât personajelor, cât și spectatorilor să se confrunte cu întrebări etice fără precedent. Una dintre problemele centrale ale acestei lumi este transformarea conștiinței și a corpurilor omenești în mărfuri. Când mintea poate fi mutată dintr-un corp în altul după voie, autonomia asupra propriului corp și consimțământul capătă dimensiuni noi. Seria explorează situații în care oamenii sunt puși cu forța în corpuri pe care nu le-au ales, ridicând probleme despre suveranitatea personală și despre etica încarcerării într-o lume unde pedeapsa poate însemna zeci sau chiar sute de ani petrecuți „în stivă”. „Moartea adevărată”, distrugerea unei stive corticale și sfârșitul definitiv al existenței unei persoane, devine crima supremă. Aceasta ridică întrebări profunde despre natura dreptății și a pedepsei.',
}
for filename in ('0010.json', '0011.json'):
    path = root / filename
    data = json.loads(path.read_text())
    for segment in data['segments']:
        segment['translation'] = translations[segment['id']]
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n')
